(function() {
    var originalTabify = $.ui.tabs.prototype._tabify;
    
    $.extend($.ui.tabs.prototype, {
        _tabify: function() {
            var self = this;
            originalTabify.apply(this, arguments);
            
            if (this.options.closable === true) {
                this.lis.filter(function() {
                    return $("span.ui-icon-circle-close", this).length === 0;
                }).not(":first").each(function() {
                    $(this).append('<a href="#"><span class="ui-icon ui-icon-circle-close"></span></a>')
                        .find("a:last")
                        .hover(function() {
                            $(this).css("cursor", "pointer");
                        }, function() {
                            $(this).css("cursor", "default");
                        })
                        .click(function() {
                            var index = self.lis.index($(this).parent());
                            if (index > -1) {
                                if (false === self._trigger("closableClick", null, 
                                    self._ui($(self.lis[index]).find("a")[0], self.panels[index]))) {
                                    return;
                                }
                                
                                // Get the panel ID and tab text before removing
                                var $tab = $(self.lis[index]);
                                var panelId = $tab.find("a").attr("href");
                                var tabText = $tab.text().trim();
                                
                                // Remove the tab
                                self.remove(index);
                                
                                // Remove the corresponding panel
                                if (panelId) {
                                    $(panelId).remove();
                                }
                                
                                // Clean up any empty tabs that might be left
                                removeEmptyTabs();
                                // Remove NiceScroll if only main_page remains
                                if ($('#tabList li').length === 1) {
                                    $(".nicescroll-rails").remove();
                                }
                            }
                            return false;
                        }).end();
                });
            }
        }
    });
    
    // Helper function to remove empty tabs
    function removeEmptyTabs() {
        $('.ui-tabs-panel').not('#main_page').each(function() {
            var $panel = $(this);
            var panelId = $panel.attr('id');
            var $tab = $('#tabList a[href="#' + panelId + '"]').closest('li');
            
            if (!$tab.length && panelId) {
                $panel.remove();
            }
        });
    }
})(jQuery);